package org.sleepwell.app;
import android.app.Activity;import android.content.*;import android.content.res.ColorStateList;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.time.LocalDate;
/** Private settings-only document flow. Selecting a document never applies it. */
public final class SettingsProfileActivity extends Activity {
 private static final int DOCUMENT=854;private SettingsProfileJob job;private SettingsProfileJob.State drawn;private final boolean[] included={true,true,true,true,true};private boolean resumed,pickerOutstanding;private String ticket="",error="";private SettingsProfileJob.Kind selected;private final Handler main=new Handler(Looper.getMainLooper());
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);job=SettingsProfileJob.get(this);if(saved!=null){boolean[] restored=saved.getBooleanArray("included");if(restored!=null&&(restored.length==4||restored.length==5))System.arraycopy(restored,0,included,0,restored.length);error=saved.getString("error","");if(job.id.equals(saved.getString("job",""))){pickerOutstanding=saved.getBoolean("picker");ticket=saved.getString("ticket","");try{selected=SettingsProfileJob.Kind.valueOf(saved.getString("kind",""));}catch(IllegalArgumentException invalid){pickerOutstanding=false;}}else error="The settings operation was interrupted. Select the document again; no import is resumed automatically.";}if(Build.VERSION.SDK_INT>=33)getOnBackInvokedDispatcher().registerOnBackInvokedCallback(android.window.OnBackInvokedDispatcher.PRIORITY_DEFAULT,this::back);render();}
 private void render(){drawn=job.state();boolean recovery=job.recovery()&&!drawn.busy;LinearLayout body=Design.page(this,false,null,n->{});RecordUi.label(this,body);RecordUi.header(body,"Settings profile",this::back);Design.space(body,14);Design.text(body,"A separate copy of selected settings",23,600,Design.INK);Design.space(body,10);Design.text(body,"Transfers appearance (including Room and Wind-down dimming), sleep-plan times, bundled-sound choices, narration presets and optional Tonight row layout. It never replaces sleep records or alarms.",14,400,Design.MUTED);Design.space(body,10);Design.text(body,"Excluded: tracking/capture settings, credentials, integrations, endpoints, provider and voice identities, local audio references, permissions, enrolled challenges, guard apps, current jobs and all runtime authority.",12,400,Design.MUTED);Design.space(body,16);
  if(recovery){Design.text(body,"Interrupted settings apply",21,600,Design.BROWN);Design.text(body,"Some supported values may have changed before an interruption. Previous values remain in a private recovery record. Restore them only after stopping alarms, tracking and playback; newer changes will block rollback instead of being overwritten.",14,400,Design.MUTED);}
  else if(drawn.phase==SettingsProfileJob.Phase.REVIEW||drawn.phase==SettingsProfileJob.Phase.EXPORT_READY){Design.text(body,drawn.phase==SettingsProfileJob.Phase.REVIEW?"Review imported values":"Review frozen export",21,600,Design.INK);if(drawn.profile!=null)try{for(String row:drawn.profile.review(this)){Design.space(body,12);Design.text(body,row,14,400,Design.INK);Design.line(body);}}catch(Exception invalid){error="The settings review is unreadable. Discard it and choose the document again.";}Design.space(body,12);Design.text(body,drawn.phase==SettingsProfileJob.Phase.REVIEW?"Apply replaces only these categories. Imported reminders, smart bedtime and Play with tracking remain off. A sleep-plan import requires existing bedtime automation, guard and per-alarm reminder overrides to be off first.":"The document records source choices, including reminder/playback preferences. Import always keeps those activation options off. Choose a trusted destination; schedule times can be private.",13,500,Design.BROWN);}
  else if(!drawn.busy&&drawn.phase!=SettingsProfileJob.Phase.CHOOSING){Design.text(body,"Export categories",17,600,Design.INK);for(int index=0;index<included.length;index++){final int category=index;CheckBox check=new CheckBox(this);check.setTypeface(Design.font(this,400));check.setTextSize(15*Appearance.scale(this));check.setTextColor(Design.INK);check.setButtonTintList(ColorStateList.valueOf(Design.BROWN));check.setMinHeight(Design.dp(this,48));check.setText(SettingsProfile.CATEGORIES[index]);check.setChecked(included[index]);check.setOnCheckedChangeListener((button,on)->included[category]=on);body.addView(check);}Design.text(body,"Local audio or playlists are unsupported. Deselect Bundled sounds to export the other categories; they are never silently substituted.",12,400,Design.MUTED);}
  if(!drawn.message.isEmpty()){Design.space(body,12);TextView status=Design.text(body,drawn.message,13,500,drawn.phase==SettingsProfileJob.Phase.ERROR?0xffa93919:Design.MUTED);status.setContentDescription("Settings profile status");status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}if(!error.isEmpty())Design.text(body,error,13,500,0xffa93919);LinearLayout footer=RecordUi.footer(body);
  if(drawn.phase==SettingsProfileJob.Phase.BLOCKED)Design.button(footer,"Retry document cleanup",true,()->{job.retryClose();render();});
  else if(drawn.busy){Design.text(footer,drawn.phase==SettingsProfileJob.Phase.APPLYING||drawn.phase==SettingsProfileJob.Phase.RECOVERING?"Committing supported settings. This step cannot be cancelled.":"Document work runs in the background. Cancelled exports can leave an empty or partial destination file.",12,400,Design.MUTED);if(drawn.phase!=SettingsProfileJob.Phase.APPLYING&&drawn.phase!=SettingsProfileJob.Phase.RECOVERING&&drawn.phase!=SettingsProfileJob.Phase.CLOSING)Design.button(footer,"Cancel document operation",false,()->{job.cancel();render();});}
  else if(recovery){Design.button(footer,"Restore previous supported settings",true,()->{if(!hasWindowFocus())return;error="";job.recover();render();});Design.button(footer,"Keep current values for now",false,this::finish);}
  else if(drawn.phase==SettingsProfileJob.Phase.CHOOSING)Design.button(footer,"Cancel document selection",false,()->{abandonChoice();render();});
  else if(drawn.phase==SettingsProfileJob.Phase.REVIEW){Design.button(footer,"Apply reviewed settings · keep activation off",true,()->{if(!hasWindowFocus())return;error="";job.apply();render();});Design.button(footer,"Refresh review against current settings",false,()->{error="";job.refresh();render();});Design.button(footer,"Cancel import · keep current settings",false,()->{error="";job.discard();render();});}
  else if(drawn.phase==SettingsProfileJob.Phase.EXPORT_READY){Design.button(footer,"Choose settings export document",true,()->choose(SettingsProfileJob.Kind.EXPORT));Design.button(footer,"Discard prepared export",false,()->{job.discard();render();});}
  else{Design.button(footer,"Prepare selected settings export",true,()->{error="";job.prepare(included);render();});Design.button(footer,"Choose settings profile to import",false,()->choose(SettingsProfileJob.Kind.IMPORT));}Design.space(footer,8);Design.text(footer,"Versions 1–2 · strict UTF-8 JSON · 64 KiB maximum · no persistent document grants",12,400,Design.MUTED);
 }
 private void choose(SettingsProfileJob.Kind kind){if(pickerOutstanding||!hasWindowFocus())return;String owned=job.choose(kind);if(owned.isEmpty())return;ticket=owned;selected=kind;pickerOutstanding=true;error="";render();try{Intent intent=new Intent(kind==SettingsProfileJob.Kind.IMPORT?Intent.ACTION_OPEN_DOCUMENT:Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json").addFlags(kind==SettingsProfileJob.Kind.IMPORT?Intent.FLAG_GRANT_READ_URI_PERMISSION:Intent.FLAG_GRANT_WRITE_URI_PERMISSION);if(kind==SettingsProfileJob.Kind.EXPORT)intent.putExtra(Intent.EXTRA_TITLE,"sleepwell-settings-"+LocalDate.now()+".json");startActivityForResult(intent,DOCUMENT);}catch(RuntimeException unavailable){pickerOutstanding=false;job.cancelledChoice(owned);ticket="";error="A document provider could not open. Try again.";render();}}
 @Override protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code!=DOCUMENT||!pickerOutstanding||isDestroyed())return;if(isFinishing()){abandonChoice();return;}pickerOutstanding=false;String owned=ticket;ticket="";try{Uri uri=data==null?null:data.getData();if(result!=RESULT_OK||uri==null){job.cancelledChoice(owned);render();return;}if(!job.document(owned,uri)){job.cancelledChoice(owned);error="This selection expired or is unsupported. Select a document again.";}}catch(RuntimeException invalid){job.cancelledChoice(owned);error="The chosen settings document could not open.";}render();}
 private final Runnable poll=new Runnable(){public void run(){if(!resumed||isFinishing()||isDestroyed())return;if(drawn!=job.state())render();main.postDelayed(this,150);}};
 @Override protected void onResume(){super.onResume();resumed=true;main.removeCallbacks(poll);main.post(poll);}@Override protected void onPause(){resumed=false;main.removeCallbacks(poll);super.onPause();}
 private void abandonChoice(){if(!pickerOutstanding)return;pickerOutstanding=false;String owned=ticket;ticket="";job.cancelledChoice(owned);}
 private void back(){if(drawn!=null&&(drawn.phase==SettingsProfileJob.Phase.APPLYING||drawn.phase==SettingsProfileJob.Phase.RECOVERING))return;abandonChoice();finish();}
 @android.annotation.SuppressLint("GestureBackNavigation") @Override public void onBackPressed(){back();}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putString("job",job.id);saved.putBooleanArray("included",included);saved.putBoolean("picker",pickerOutstanding);saved.putString("ticket",ticket);saved.putString("error",error);if(selected!=null)saved.putString("kind",selected.name());}
 @Override protected void onDestroy(){resumed=false;main.removeCallbacksAndMessages(null);if(isFinishing())abandonChoice();super.onDestroy();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);}
}
